const $=id=>document.getElementById(id);
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('tarrasque-'+key))??fallback}catch{return fallback}};
const save=(key,value)=>{try{localStorage.setItem('tarrasque-'+key,JSON.stringify(value));return true}catch{notify('Não foi possível salvar neste navegador.');return false}};
let page='personagem',mode='',collapsed=read('collapsed',false)===true,profile=read('profile','Aventureiro');
if(typeof profile!=='string')profile='Aventureiro';
const records={personagem:read('personagem',[]),campanha:read('campanha',[])};
for(const key in records)if(!Array.isArray(records[key]))records[key]=[];
const mobile=matchMedia('(max-width:768px)');let timer;
function notify(message){$('toast').textContent=message;clearTimeout(timer);timer=setTimeout(()=>$('toast').textContent='',3500)}
function user(){ $('user-name').textContent=profile;$('avatar').textContent=profile.trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'AV'}
function sidebar(){ $('sidebar').classList.toggle('collapsed',!mobile.matches&&collapsed);const expanded=mobile.matches?$('sidebar').classList.contains('mobile-open'):!collapsed;$('toggle').setAttribute('aria-expanded',expanded);$('toggle').setAttribute('aria-label',expanded?'Recolher sidebar':'Expandir sidebar');$('toggle').title=expanded?'Recolher sidebar':'Expandir sidebar';$('backdrop').hidden=!(mobile.matches&&expanded);$('sidebar').inert=mobile.matches&&!expanded}
$('toggle').onclick=()=>{if(mobile.matches)$('sidebar').classList.toggle('mobile-open');else{collapsed=!collapsed;save('collapsed',collapsed)}sidebar()};
function closeNav(){ $('sidebar').classList.remove('mobile-open');sidebar()}
$('backdrop').onclick=()=>{closeNav();$('toggle').focus()};mobile.addEventListener('change',closeNav);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('dialog').open&&mobile.matches){closeNav();$('toggle').focus()}});
function render(){const character=page==='personagem';const name=character?'Personagem':'Campanha';$('crumb').textContent=name;$('page-title').replaceChildren(document.createTextNode(name),Object.assign(document.createElement('span'),{textContent:'.'}));$('subtitle').textContent=character?'Dê vida a quem vai fazer parte da sua história.':'Reúna seu grupo. Construa um mundo. Viva uma aventura.';$('new-top').querySelector('span').textContent=character?'Novo personagem':'Nova campanha';$('list-title').firstChild.textContent=character?'Meus personagens ':'Minhas campanhas ';$('count').textContent=records[page].length;$('empty-title').innerHTML=character?'Uma ficha em branco.<br>Infinitas possibilidades.':'Um novo mundo.<br>Uma história em conjunto.';$('empty-copy').textContent=character?'Todo herói tem um começo. Crie seu primeiro personagem e prepare-se para escrever o próximo capítulo.':'Toda aventura precisa de um cenário. Crie sua primeira campanha e dê início à jornada do seu grupo.';$('new-empty').querySelector('span').textContent=character?'Criar meu personagem':'Criar minha campanha';$('empty-foot').textContent=character?'Um nome. Uma origem. Uma nova lenda.':'Um grupo. Um mundo. Muitas histórias.';$('empty').hidden=records[page].length>0;$('cards').replaceChildren();for(const item of records[page]){const card=document.createElement('article');card.className='card';const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');const use=document.createElementNS(icon.namespaceURI,'use');use.setAttribute('href',character?'#person':'#map');icon.append(use);const title=document.createElement('h2');title.textContent=item.name;const text=document.createElement('p');text.textContent=item.detail||'Uma nova história começa aqui.';const label=document.createElement('small');label.textContent=character?'PERSONAGEM':'CAMPANHA';card.append(icon,title,text,label);$('cards').append(card)}document.querySelectorAll('[data-page]').forEach(button=>{const active=button.dataset.page===page;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')})}
document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>{page=button.dataset.page;render();closeNav()});
function open(kind){mode=kind;if(kind==='settings'){ $('dialog-title').textContent='Configurações';$('dialog-body').innerHTML='<label for="theme">Tema da aplicação<select id="theme"><option value="dark">Original · Odysseus</option><option value="light">Light</option><option value="forest">Forest</option><option value="terminal">Terminal</option></select></label><p class="hint">Sua preferência de aparência será salva neste navegador.</p>';try{$('theme').value=localStorage.getItem('tarrasque-theme')||'dark'}catch{}}else if(kind==='profile'){ $('dialog-title').textContent='Seu perfil';$('dialog-body').innerHTML='<label for="name">Nome de exibição<input id="name" required maxlength="32" autocomplete="nickname"></label>';$('name').value=profile}else{const character=page==='personagem';$('dialog-title').textContent=character?'Novo personagem':'Nova campanha';$('dialog-body').innerHTML='<label for="name">Nome '+(character?'do personagem':'da campanha')+'<input id="name" required maxlength="60" placeholder="'+(character?'Como seu herói se chama?':'Como sua aventura se chama?')+'"></label><label for="detail">'+(character?'Classe ou origem':'Cenário ou sistema')+'<input id="detail" maxlength="120" placeholder="'+(character?'Ex.: Elfo · Mago':'Ex.: Forgotten Realms · D&D 5e')+'"></label><p class="hint">Salvo apenas neste navegador.</p>'}$('dialog').showModal()}
$('settings').onclick=()=>open('settings');$('profile').onclick=()=>open('profile');$('new-top').onclick=$('new-empty').onclick=()=>open('new');$('close').onclick=$('cancel').onclick=()=>$('dialog').close();
$('form').onsubmit=e=>{e.preventDefault();if(mode==='settings'){const theme=$('theme').value;try{localStorage.setItem('tarrasque-theme',theme)}catch{notify('Não foi possível salvar o tema.');return}applyTheme(theme)}else{const name=$('name').value.trim();if(!name){$('name').setCustomValidity('Digite um nome.');$('name').reportValidity();$('name').oninput=()=>$('name').setCustomValidity('');return}if(mode==='profile'){if(!save('profile',name))return;profile=name;user()}else{const next=[...records[page],{name,detail:$('detail').value.trim()}];if(!save(page,next))return;records[page]=next;render()}}$('dialog').close();notify('Salvo com sucesso.')};
user();sidebar();render();
